<template><view class="governance"><k-topbar :title="roundId?'匿名评审':'大众评审'" back/>
    <k-subscribe scenes="mediation_jury" label="订阅评审提醒" /><view class="gov-body"><text v-if="error" class="gov-error">{{error}}</text><text v-if="feedback" class="gov-success">{{feedback}}</text><template v-if="!roundId"><text class="gov-title">用认真倾听，帮助解决分歧</text><text class="gov-muted">独立评议，保护双方隐私。完成有效评审奖励5积分，优质评审额外奖励10积分。</text><view class="gov-section"><text class="gov-heading">我的参与意愿</text><text v-if="context.juror?.coreMember" class="gov-badge">核心评审员</text><text v-else-if="context.juror?.coreEligible" class="gov-muted">已符合核心评审条件，开启参与意愿后可进入核心评审池。</text><view class="gov-tabs"><button :class="{active:kind==='user'}" @click="kind='user'">用户评审员</button><button v-if="context.canMerchant" :class="{active:kind==='merchant'}" @click="kind='merchant'">店家评审员</button></view><picker v-if="kind==='merchant'" :range="context.merchantStores||[]" range-key="storeName" @change="store=context.merchantStores[$event.detail.value]"><view class="gov-select">{{store?.storeName||'选择合作门店'}}</view></picker><view class="gov-check"><switch :checked="willing" color="#a86d39" @change="willing=$event.detail.value"/><text>愿意接收匿名评审邀请</text></view><button class="primary" :disabled="busy" @click="save">保存参与意愿</button><text class="gov-time">{{context.juror?.eligible?'已满足基础条件，系统会按利益回避规则随机邀请':'达到资格条件后才会收到邀请，保存意愿不会直接获得评审资格'}}</text><text class="gov-muted">用户需信用分≥90、无违规且完成至少3次换工/兼职/住宿；店家需合作满3个月、评分≥4.5且无未闭环投诉。</text></view><text class="gov-heading">我的评审邀请</text><text v-if="!rounds.length" class="gov-empty">暂时没有评审邀请</text><view v-for="r in rounds" :key="r.roundId" class="gov-item" @click="go('/pages/governance/jury?id='+r.roundId)"><view class="gov-row"><text class="gov-item-title">{{r.category}}</text><text class="gov-badge">{{r.choice?'已投票':r.status==='open'?'待评议':'已结束'}}</text></view><text class="gov-time">截止 {{r.deadline}}</text><text v-if="r.quality==='1'" class="gov-muted">优质评审奖励已记入积分</text></view><view class="gov-actions"><button @click="go('/pages/governance/badges')">查看徽章与积分</button></view></template><template v-else-if="detail"><text class="gov-title">{{detail.category}}</text><text class="gov-muted">请勿尝试辨认、联系当事人或转发材料。评审员彼此匿名。</text><view class="gov-section"><text class="gov-heading">事件经过</text><text class="gov-copy">{{detail.anonymousNarrative}}</text><text class="form-label">双方诉求</text><text class="gov-copy">{{detail.anonymousClaims}}</text><EvidenceView :files="detail.evidence||[]" anonymous/></view><template v-if="!detail.choice&&detail.status==='open'"><text class="gov-heading">你的独立判断</text><view class="gov-actions"><button v-for="c in choices" :key="c.value" :class="{active:choice===c.value}" @click="choice=c.value">{{c.label}}</button></view><textarea v-model="reason" maxlength="1000" placeholder="选填，简要说明判断依据，最多1000字"/><text class="gov-muted">提交后不能重复投票。请勿在理由中写入个人联系方式。</text><button class="primary" :disabled="busy||!choice||reason.trim().length>1000" @click="vote">提交评审意见</button></template><template v-else><text class="gov-heading">{{detail.choice?'你已提交评审':'评审已截止'}}</text><text class="gov-copy">{{choices.find(c=>c.value===detail.choice)?.label}}</text><text class="gov-copy">{{detail.reason}}</text></template></template></view></view></template>
<script setup>
import {ref} from 'vue'
import {onLoad,onShow} from '@dcloudio/uni-app'
import {governanceGet as get,governancePost as post,juryChoices as choices} from '@/common/governance.js'
import EvidenceView from './components/evidence-view.vue'
const roundId=ref(0),detail=ref(null),rounds=ref([]),context=ref({}),kind=ref('user'),store=ref(null),willing=ref(false),error=ref(''),feedback=ref(''),busy=ref(false),choice=ref(''),reason=ref('')
const go=url=>uni.navigateTo({url})
async function load(){try{if(roundId.value)detail.value=(await get('jury/'+roundId.value)).data;else{context.value=(await get('context')).data;const j=context.value.juror;kind.value=j.kind;willing.value=j.willing==='1';store.value=context.value.merchantStores?.find(s=>s.storeId===j.storeId)||null;rounds.value=(await get('jury')).data}}catch(e){error.value=e.message}}
async function save(){busy.value=true;error.value='';try{await post('juror',{kind:kind.value,storeId:store.value?.storeId,willing:willing.value});feedback.value='参与意愿已保存';await load()}catch(e){error.value=e.message}finally{busy.value=false}}
async function vote(){busy.value=true;error.value='';try{await post('jury/'+roundId.value+'/vote',{choice:choice.value,reason:reason.value});feedback.value='评审已提交，有效评审积分已入账';await load()}catch(e){error.value=e.message}finally{busy.value=false}}
onLoad(q=>roundId.value=Number(q.id)||0);onShow(load)
</script><style lang="scss">@import './governance.scss';</style>
